    match self {
        Self::Version { backend, .. }
        | Self::Prefix { backend, .. }
        | Self::Ref { backend, .. }
        | Self::Path { backend, .. }
        | Self::Sub { backend, .. }
        | Self::System { backend, .. } => backend,
    }
