/// Strip trailing `[...]` opts from a string, e.g. `"foo[a=1]"` → `"foo"`.
pub(crate) fn strip_opts(s: &str) -> String {
    split_bracketed_opts(s)
        .map(|(name, _)| name.to_string())
        .unwrap_or_else(|| s.to_string())
}

/// Whether a plugin installed under `short` takes precedence over the registry entry.
///
/// A plugin whose backend is disabled by `disable_backends` does not, unless the requested
/// version is already installed through that same backend. `disable_backends` is an
/// install-time guard that intentionally keeps existing tools usable, but a leftover plugin
/// must not route a new version to a disabled backend when the registry offers an enabled
/// backend (discussions/6021, discussions/12921).
fn plugin_overrides_registry(short: &str, requested_version: Option<&str>) -> bool {
    let Some(plugin_type) = install_state::get_plugin_type(short) else {
        return false;
    };
    let backend_type = match plugin_type {
        PluginType::Asdf => BackendType::Asdf,
        PluginType::Vfox => BackendType::Vfox,
        PluginType::VfoxBackend => BackendType::VfoxBackend(short.to_string()),
        PluginType::Package => return true,
    };
    if !backend::is_disabled_backend_type(&backend_type) {
        return true;
    }
    if install_state::backend_type(short).ok().flatten() != Some(backend_type) {
        return false;
    }
    let Some(requested_version) = requested_version else {
        return !install_state::list_versions(short).is_empty();
    };
    let Some(full) = install_state::get_tool_full(short) else {
        return false;
    };
    let backend = BackendArg::new(short.to_string(), Some(full));
    backend::arg_to_backend(backend).is_some_and(|backend| {
        !backend
            .list_installed_versions_matching(requested_version)
            .is_empty()
    })
}

