        &self,
        config: &Arc<Config>,
        tv: &ToolVersion,
        check_symlink: bool,
    ) -> Result<bool> {
        Ok(self.is_version_installed(config, tv, check_symlink))
    }

    async fn is_install_satisfied_or_false(
        &self,
        config: &Arc<Config>,
        tv: &ToolVersion,
        check_symlink: bool,
    ) -> bool {
        self.is_install_satisfied(config, tv, check_symlink)
            .await
            .unwrap_or_else(|err| {
                debug!(
                    "is_install_satisfied check failed for {}: {err:#}",
                    tv.style()
                );
                false
            })
    }
    async fn is_version_outdated(&self, config: &Arc<Config>, tv: &ToolVersion) -> bool {
        let latest = match tv.latest_version(config).await {
            Ok(latest) => latest,
            Err(e) => {
                warn!(
                    "Error getting latest version for {}: {:#}",
                    self.ba().to_string(),
                    e
                );
                return false;
            }
        };
        !self.is_version_installed(config, tv, true) || is_outdated_version(&tv.version, &latest)
    }
    fn symlink_path(&self, tv: &ToolVersion) -> Option<PathBuf> {
        let path = tv.install_path();
        if !path.is_symlink() {
            return None;
        }
        // Only skip symlinks pointing within installs (user aliases, not backend-managed)
        if let Ok(Some(target)) = file::resolve_symlink(&path) {
            let target = if target.is_absolute() {
                target
            } else {
                path.parent().unwrap_or(&path).join(&target)
            };
            // Canonicalize to resolve any ".." components before checking.
            // If target doesn't exist (canonicalize fails), don't skip - treat as needing install
            let target = canonicalize_cached(&target)?;
            // Canonicalize INSTALLS too for consistent comparison (handles symlinked data dirs)
            let installs =
                canonicalize_cached(&dirs::INSTALLS).unwrap_or(dirs::INSTALLS.to_path_buf());
            if target.starts_with(&installs) {
                return Some(path);
            }
            // Also check shared install directories
            for shared_dir in env::shared_install_dirs() {
                let shared = canonicalize_cached(&shared_dir).unwrap_or(shared_dir.to_path_buf());
                if target.starts_with(&shared) {
                    return Some(path);
                }
            }
        }
        None
    }
    fn list_installed_versions_matching(&self, query: &str) -> Vec<String> {
        let versions = self.list_installed_versions();
        // No async config lookup available here; fall back to inline/registry
        // opts, which is the best we have for a sync path.
        let filter = !self.include_prereleases(&self.ba().opts());
        self.fuzzy_match_filter(versions, query, filter)
    }
    async fn list_versions_matching(
        &self,
        config: &Arc<Config>,
        query: &str,
    ) -> eyre::Result<Vec<String>> {
        let opts = config.get_tool_opts_with_overrides(self.ba()).await?;
        self.list_versions_matching_with_selection_options(config, query, &opts, None, false)
            .await
    }

    /// List versions matching a query, optionally filtered by release date.
    /// Use this when you have a `before_date` from ResolveOptions.
    async fn list_versions_matching_with_opts(
        &self,
        config: &Arc<Config>,
        query: &str,
        before_date: Option<Timestamp>,
        refresh: bool,
    ) -> eyre::Result<Vec<String>> {
        let opts = config.get_tool_opts_with_overrides(self.ba()).await?;
    list_plugins().get(short).cloned()
}

/// Every installed tool. This enumerates the whole installs dir (a readdir per
/// tool plus stats per version) — reach for [`get_tool`] instead when only
/// specific tools matter.
///
/// A failed scan is reported as an error rather than as an empty set: callers
/// that *remove* things treat "no tools installed" as authoritative (shim
/// rebuilding deletes every shim it cannot account for), so an unreadable
/// installs dir must not be indistinguishable from an empty one. Note a
/// missing installs dir is not an error — that reads as genuinely empty.
pub(crate) fn try_list_tools() -> Result<Arc<BTreeMap<String, InstallStateTool>>> {
    full_scan_tools()
}

/// [`try_list_tools`] for callers that only display or enumerate, where a
/// warning is a better outcome than aborting. Never use this to decide what to
/// delete.
pub(crate) fn list_tools() -> Arc<BTreeMap<String, InstallStateTool>> {
    try_list_tools().unwrap_or_else(|err| {
        warn!("failed to scan installed tools: {err:#}");
        Arc::new(Default::default())
    })
}

pub(crate) fn backend_type(short: &str) -> Result<Option<BackendType>> {
    let backend_type = with_tool(short, |ist| ist.full.clone())
        .flatten()
        .and_then(|full| {
            full.split_once(':')
                .map(|(backend, _)| BackendType::guess(backend))
        });
    if let Some(BackendType::Unknown) = backend_type
        && let Some((plugin_name, _)) = short.split_once(':')
        && let Some(PluginType::VfoxBackend) = get_plugin_type(plugin_name)
    {
        return Ok(Some(BackendType::VfoxBackend(plugin_name.to_string())));
    }
    Ok(backend_type)
}

pub(crate) fn list_versions(short: &str) -> Vec<String> {
    with_tool(short, |tool| tool.versions.clone()).unwrap_or_default()
}


